solution.solution.cpp:
#include <string_view>

enum class Direction
{
    north,
    east,
    south,
    west,
};

Direction turnRight(Direction d)
{
    switch (d)
    {
    case Direction::north: return Direction::east;
    case Direction::east:  return Direction::south;
    case Direction::south: return Direction::west;
    case Direction::west:  return Direction::north;
    }
    return Direction::north;
}

std::string_view name(Direction d)
{
    switch (d)
    {
    case Direction::north: return "north";
    case Direction::east:  return "east";
    case Direction::south: return "south";
    case Direction::west:  return "west";
    }
    return "unknown";
}

unitTests:
TEST("turnRight") { CHECK(turnRight(Direction::north) == Direction::east); CHECK(turnRight(Direction::east) == Direction::south); CHECK(turnRight(Direction::south) == Direction::west); CHECK(turnRight(Direction::west) == Direction::north); }
TEST("four right turns bring you back") { Direction d{ Direction::south }; for (int i{ 0 }; i < 4; ++i) d = turnRight(d); CHECK(d == Direction::south); }
TEST("name") { CHECK_EQ(name(Direction::north), "north"); CHECK_EQ(name(Direction::east), "east"); CHECK_EQ(name(Direction::south), "south"); CHECK_EQ(name(Direction::west), "west"); }

